157	        const maxDataCnt = labelModel.get(['data', 'maxCount']) || 10;
158	        const maxSeriesCnt = labelModel.get(['series', 'maxCount']) || 10;
159	        const displaySeriesCnt = Math.min(seriesCnt, maxSeriesCnt);
